const express = require('express');
const { promisify } = require('util');
const execFile = promisify(require('child_process').execFile);
const crypto = require('crypto');
const net = require('net');

const app = express();
app.use(express.json());

// Resolver configuration
const DEFAULT_RESOLVER = '1.1.1.1';

// Rate limiting state
const requestCounts = new Map();

// Periodically purge expired rate-limit records to prevent unbounded
// memory growth (memory-exhaustion DoS via many distinct source IPs).
const cleanupInterval = setInterval(() => {
  const now = Date.now();
  for (const [key, record] of requestCounts) {
    if (now > record.resetTime) {
      requestCounts.delete(key);
    }
  }
}, 60000);
// Do not keep the event loop alive solely for the cleanup timer.
if (cleanupInterval.unref) cleanupInterval.unref();

function rateLimit(req, res, next) {
  const key = req.ip;
  const now = Date.now();
  const windowMs = 60000;
  const max = 30;

  if (!requestCounts.has(key)) {
    requestCounts.set(key, { count: 1, resetTime: now + windowMs });
    return next();
  }

  const record = requestCounts.get(key);
  if (now > record.resetTime) {
    record.count = 1;
    record.resetTime = now + windowMs;
    return next();
  }

  if (record.count >= max) {
    return res.status(429).json({ error: 'Rate limit exceeded' });
  }

  record.count++;
  next();
}

function isValidDomain(domain) {
  if (!domain || typeof domain !== 'string') return false;
  if (domain.length > 253) return false;
  const labels = domain.split('.');
  if (labels.length < 2) return false;
  for (const label of labels) {
    if (label.length === 0 || label.length > 63) return false;
    if (!/^[a-zA-Z0-9]([a-zA-Z0-9-]*[a-zA-Z0-9])?$/.test(label)) return false;
  }
  return true;
}

function isValidRecordType(type) {
  const allowed = ['A', 'AAAA', 'MX', 'TXT', 'NS', 'CNAME', 'SOA', 'PTR'];
  return allowed.includes(type);
}

/**
 * Validates and selects resolver IP from user input.
 * Accepts raw IP strings from request body for flexibility.
 * Uses net.isIP() for strict IP validation.
 */
function selectResolver(rawInput) {
  if (!rawInput || typeof rawInput !== 'string') {
    return DEFAULT_RESOLVER;
  }

  const cleaned = rawInput.trim();

  // Strict IP validation using Node's built-in net module
  // net.isIP returns 4 for IPv4, 6 for IPv6, 0 for invalid
  const ipVersion = net.isIP(cleaned);
  if (ipVersion === 0) {
    return DEFAULT_RESOLVER;
  }

  // Additional security: block private/internal IP ranges
  if (isPrivateIP(cleaned)) {
    return DEFAULT_RESOLVER;
  }

  return cleaned;
}

function isPrivateIP(ip) {
  // Block RFC1918, loopback, link-local, and other internal ranges
  const privatePatterns = [
    /^10\./,
    /^172\.(1[6-9]|2[0-9]|3[01])\./,
    /^192\.168\./,
    /^127\./,
    /^169\.254\./,
    /^0\./,
    /^::1$/,
    /^fe80:/i,
    /^fc00:/i,
    /^fd[0-9a-f]{2}:/i
  ];
  return privatePatterns.some(pattern => pattern.test(ip));
}

async function performLookup(domain, recordType, resolver) {
  const args = [
    `@${resolver}`,
    domain,
    recordType,
    '+short',
    '+timeout=5',
    '+tries=2',
    '+norecurse'
  ];

  try {
    const { stdout, stderr } = await execFile('/usr/bin/dig', args, {
      timeout: 10000,
      maxBuffer: 1024 * 512,
      env: {} // clean environment
    });

    if (stderr && stderr.trim()) {
      throw new Error('DNS lookup failed');
    }

    return stdout.trim().split('\n').filter(line => line.length > 0);
  } catch (err) {
    if (err.killed) throw new Error('DNS lookup timed out');
    throw new Error('DNS lookup failed');
  }
}

app.post('/api/dns/resolve', rateLimit, async (req, res) => {
  try {
    const { domain, type, resolver_preference } = req.body;

    if (!domain || !type) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    const normalizedDomain = String(domain).toLowerCase().trim();
    const normalizedType = String(type).toUpperCase().trim();

    if (!isValidDomain(normalizedDomain)) {
      return res.status(400).json({ error: 'Invalid domain' });
    }

    if (!isValidRecordType(normalizedType)) {
      return res.status(400).json({ error: 'Invalid record type' });
    }

    // Select resolver - accepts raw IP input but validates strictly
    const resolverIP = selectResolver(resolver_preference);

    const results = await performLookup(normalizedDomain, normalizedType, resolverIP);

    return res.json({
      domain: normalizedDomain,
      type: normalizedType,
      results,
      timestamp: new Date().toISOString()
    });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

app.listen(3000, '127.0.0.1');
module.exports = app;
